# -*- coding: utf-8 -*-
from gen2 import *

m1 = M(('Столбчатая диаграмма', 'A bar chart'),
 [('r', 'a', 'Понедельник', 'Monday', 0, 20, 1, 12), ('r', 'b', 'Вторник', 'Tuesday', 0, 20, 1, 8), ('r', 'c', 'Среда', 'Wednesday', 0, 20, 1, 15), ('r', 'd', 'Четверг', 'Thursday', 0, 20, 1, 10), ('r', 'e', 'Пятница', 'Friday', 0, 20, 1, 18)],
 [('Всего за 5 дней', 'Total over 5 days'), ('Больше всего', 'The most'), ('Меньше всего', 'The least'), ('Разница наибольшего и наименьшего', 'Difference between greatest and least')],
 'Сколько лепёшек продали за день. Высота столбика показывает число, ось начинается с нуля.', 'How many flatbreads were sold per day. The height of a bar shows the number; the axis starts at zero.', ('Продажи лепёшек по дням недели', 'Flatbread sales by day of the week'),
 r'''const val=[v.a,v.b,v.c,v.d,v.e],days=U(["Пн","Вт","Ср","Чт","Пт"],["Mon","Tue","Wed","Thu","Fri"]);let g=L(60,20,60,200,COL.ink,2)+L(60,200,570,200,COL.ink,2);
 for(let t=0;t<=20;t+=5)g+=L(56,200-t*8.5,570,200-t*8.5,"#e3e1da",1)+TX(52,204-t*8.5,t,COL.mut,10,"end");
 val.forEach((x,i)=>{const h=x*8.5,X0=85+i*97;g+=R(X0,200-h,70,h,i%2?COL.b:COL.a,"none",0,3)+TX(X0+35,194-h,x,COL.ink,14,"middle",600)+TX(X0+35,220,days[i],COL.mut,12)});
 const mx=Math.max(...val),mn=Math.min(...val);return {svg:g,st:[val.reduce((s,x)=>s+x,0),days[val.indexOf(mx)]+" ("+mx+")",days[val.indexOf(mn)]+" ("+mn+")",mx-mn],fb:U("Самый высокий столбик — "+mx+", самый низкий — "+mn+"; разница "+(mx-mn)+".","The tallest bar is "+mx+", the shortest "+mn+"; the difference is "+(mx-mn)+".")}''')

m2 = M(('Обрезанная ось: как диаграмма обманывает', 'The truncated axis: how a chart misleads'),
 [('r', 'p', 'Значение A', 'Value A', 30, 60, 1, 42), ('r', 'q', 'Значение B', 'Value B', 30, 60, 1, 45), ('r', 's', 'Ось начинается с', 'The axis starts at', 0, 40, 5, 35)],
 [('Настоящее отношение B : A', 'True ratio B : A'), ('На картинке кажется B : A', 'On the picture B : A looks like'), ('Ось начинается с', 'The axis starts at')],
 'Двигайте начало оси. Если ось начинается не с нуля, небольшая разница выглядит огромной.', 'Move the start of the axis. If it does not begin at zero, a small difference looks huge.', ('Два столбика: A и B', 'Two bars: A and B'),
 r'''const st=Math.min(v.s,Math.min(v.p,v.q)-5),A=v.p,B=v.q,top=Math.max(A,B)+3,hA=(A-st)/(top-st)*170,hB=(B-st)/(top-st)*170;
 let g=L(100,20,100,200,COL.ink,2)+L(100,200,500,200,COL.ink,2)+R(150,200-hA,100,hA,COL.a,"none",0,3)+R(330,200-hB,100,hB,COL.b,"none",0,3)+TX(200,220,"A = "+A,COL.ink,14,"middle",600)+TX(380,220,"B = "+B,COL.ink,14,"middle",600)+TX(96,204,st,COL.mut,11,"end")+TX(96,34,top,COL.mut,11,"end");
 return {svg:g,st:[fnum(B/A,2),fnum(hB/hA,2),st],fb:st===0?U("Ось с нуля — картинка честная: высоты пропорциональны значениям.","The axis starts at zero — the picture is honest: the heights are proportional to the values."):U("Столбик B кажется в "+fnum(hB/hA,2)+" раза выше, чем A, хотя на самом деле лишь в "+fnum(B/A,2)+" раза.","Bar B looks "+fnum(hB/hA,2)+" times taller than A although it is really only "+fnum(B/A,2)+" times.")}''')

m3 = M(('Линейный график: температура за сутки', 'A line graph: temperature through the day'),
 [('r', 'h', 'Номер замера (каждые 3 часа)', 'Measurement number (every 3 hours)', 0, 7, 1, 4)],
 [('Время', 'Time'), ('Температура', 'Temperature'), ('Изменение с предыдущего замера', 'Change since the previous reading'), ('Самая высокая температура', 'Highest temperature')],
 'Точки соединены линией: так видно, как величина меняется со временем. (Данные придуманы для примера.)', 'The points are joined by a line so we can see how a quantity changes with time. (The data are invented as an example.)', ('Температура воздуха в течение суток', 'Air temperature through a day'),
 r'''const T_=[3,2,1,6,12,16,13,7],H=[0,3,6,9,12,15,18,21],G=Gr({x0:0,x1:21,y0:-2,y1:18,L:55,T:15,W:500,H:190});let g=G.grid(3,4);
 g+=pline(H.map((h,i)=>[G.X(h),G.Y(T_[i])]),COL.b,3);H.forEach((h,i)=>{g+=G.pt(h,T_[i],i===v.h?COL.a:COL.b,i===v.h?8:4)});
 g+=TX(300,238,U("часы","hours"),COL.mut,11)+TX(24,20,"°C",COL.mut,11);const i=v.h;
 return {svg:g,st:[H[i]+":00",T_[i]+" °C",i?(T_[i]-T_[i-1]>=0?"+":"")+(T_[i]-T_[i-1])+" °C":"—","16 °C ("+U("в 15:00","at 15:00")+")"],fb:i&&T_[i]>T_[i-1]?U("Температура растёт: линия идёт вверх.","The temperature is rising: the line goes up."):i&&T_[i]<T_[i-1]?U("Температура падает: линия идёт вниз.","The temperature is falling: the line goes down."):U("Первый замер — отправная точка.","The first reading is the starting point.")}''')

chapter('13', '13-data-charts.html', 'II', ('Таблицы и диаграммы', 'Tables and charts'),
 ('Как читать диаграммы и графики — и как не дать обмануть себя неудачной осью.', 'How to read charts and graphs — and how not to be fooled by an unlucky axis.'),
 ('На диаграмме один столбик втрое выше другого.\n\nЗначит ли это, что значение в нём втрое больше?', 'On a chart one bar is three times taller than another.\n\nDoes that mean its value is three times greater?'),
 ('Разгадка: не обязательно', 'The answer: not necessarily'),
 ('Высота столбика пропорциональна значению, только если ось начинается с нуля. Если ось «обрезана» (например, начинается с 35), значения 42 и 45 покажутся столбиками высотой 7 и 10 — разница выглядит огромной, хотя настоящее отношение 45 : 42 ≈ 1,07. Всегда смотрите, с чего начинается ось.', 'The height of a bar is proportional to the value only if the axis starts at zero. If the axis is “truncated” (starting at 35, say), the values 42 and 45 look like bars of height 7 and 10 — the difference looks huge, although the true ratio 45 : 42 ≈ 1.07. Always look where the axis starts.'),
 [S('bar', 'Таблицы и столбчатые диаграммы', 'Tables and bar charts', ('Данные удобно собирать в <strong>таблицу</strong>, а потом рисовать <strong>столбчатую диаграмму</strong>: высота столбика равна числу. На диаграмме сразу видно, где больше, где меньше, и на сколько. Всегда подписывайте оси и столбики.', 'It is convenient to put data in a <strong>table</strong> and then draw a <strong>bar chart</strong>: the height of a bar equals the number. On a chart you see at once where there is more, where less, and by how much. Always label the axes and bars.'),
    ('разница = наибольшее − наименьшее', 'размах данных', 'the range of the data'), m1),
  S('trunc', 'Честная и нечестная ось', 'An honest and a dishonest axis', ('Столбики сравнивают по высоте, поэтому ось должна начинаться с <strong>нуля</strong>. Если ось начинается выше, столбики кажутся сильно разными. Это приём рекламы и политики; умеете читать оси — вас не обманут.', 'Bars are compared by height, so the axis must start at <strong>zero</strong>. If it starts higher, the bars look very different. This is a trick of advertising and politics; if you can read axes, you will not be fooled.'),
    ('B : A = 45 : 42 ≈ 1,07', 'а не «в 3 раза»', 'not “3 times”'), m2),
  S('line', 'Линейные графики', 'Line graphs', ('Если величина меняется со временем (температура, цена, рост), точки соединяют линией. Линия идёт вверх — величина растёт, вниз — падает, горизонтально — не меняется. По графику можно прочитать значение в любой момент и найти наибольшее значение.', 'If a quantity changes with time (temperature, price, height), the points are joined by a line. The line goes up — the quantity grows, down — it falls, flat — it does not change. From a graph we can read the value at any moment and find the greatest value.'),
    ('рост: линия вверх', 'падение: линия вниз', 'rise: line up; fall: line down'), m3)],
 [TK(('Прочитать диаграмму', 'Reading a chart'), ('За 5 дней продали 12, 8, 15, 10 и 18 лепёшек. Сколько всего и на сколько больше в самый удачный день, чем в самый слабый?', 'Over 5 days 12, 8, 15, 10 and 18 flatbreads were sold. How many in all, and by how many is the best day better than the worst?'), '12, 8, 15, 10, 18', 'Всего 12 + 8 + 15 + 10 + 18 = 63. Наибольшее 18, наименьшее 8, разница 18 − 8 = 10.', ('63; на 10.', '63; by 10.')),
  TK(('Обман осью', 'Fooled by the axis'), ('Ось на диаграмме начинается с 35. Значения 42 и 45. Во сколько раз кажется выше второй столбик и каково настоящее отношение?', 'The chart axis starts at 35. The values are 42 and 45. How many times taller does the second bar seem and what is the true ratio?'), '42 и 45, ось с 35', 'Высоты: 42 − 35 = 7 и 45 − 35 = 10. Кажется 10 : 7 ≈ 1,43. Настоящее 45 : 42 ≈ 1,07.', ('Кажется ≈ 1,4, на деле ≈ 1,07.', 'Seems ≈ 1.4, in fact ≈ 1.07.')),
  TK(('Рост по графику', 'Rise on a graph'), ('Температура в 9:00 была 6 °C, а в 12:00 — 12 °C. На сколько градусов она выросла?', 'At 9:00 the temperature was 6 °C and at 12:00 — 12 °C. By how many degrees did it rise?'), '6 °C → 12 °C', '12 − 6 = 6.', ('На 6 °C.', 'By 6 °C.')),
  TK(('Собрать таблицу', 'Make a table'), ('В классе любимые цвета: красный — 7 человек, синий — 9, зелёный — 5. Сколько человек в классе и какой столбик будет самым высоким?', 'Favourite colours in a class: red — 7 pupils, blue — 9, green — 5. How many pupils and which bar is tallest?'), '7, 9, 5', '7 + 9 + 5 = 21. Самый высокий — синий (9).', ('21 человек; синий.', '21 pupils; blue.')),
  TK(('Какая высота', 'What height'), ('Масштаб: 1 клетка по высоте — 2 единицы. Какой высоты должен быть столбик для значения 14?', 'Scale: 1 square of height is 2 units. How tall must the bar be for the value 14?'), '1 клетка = 2', '14 : 2 = 7.', ('7 клеток.', '7 squares.'))],
 [Q('Откуда должна начинаться ось у столбчатой диаграммы?', 'Where must the axis of a bar chart start?', ('С нуля', 'From zero'), ('С любого числа', 'From any number'), ('С наибольшего значения', 'From the greatest value'), ('Иначе высота не пропорциональна значению.', 'Otherwise the height is not proportional to the value.')),
  Q('Линия на графике идёт вверх. Значит величина', 'The line on a graph goes up. So the quantity', ('растёт', 'is rising'), ('падает', 'is falling'), ('не меняется', 'does not change'), ('Вверх — рост.', 'Up means rising.')),
  Q('Данные 12, 8, 15, 10, 18. Сколько всего?', 'The data 12, 8, 15, 10, 18. What is the total?', '63', '53', '60', ('12 + 8 + 15 + 10 + 18 = 63.', '12 + 8 + 15 + 10 + 18 = 63.')),
  Q('Какое значение наибольшее: 12, 8, 15, 10, 18?', 'Which value is the greatest: 12, 8, 15, 10, 18?', '18', '15', '8', ('18 — наибольшее.', '18 is the greatest.')),
  Q('Чему равна разница наибольшего и наименьшего значения в 12, 8, 15, 10, 18?', 'What is the difference between the greatest and least value in 12, 8, 15, 10, 18?', '10', '18', '8', ('18 − 8 = 10.', '18 − 8 = 10.')),
  Q('Зачем подписывать оси диаграммы?', 'Why label the axes of a chart?', ('Чтобы было понятно, что и в чём измеряется', 'So it is clear what is measured and in what'), ('Для красоты', 'For decoration'), ('Это не нужно', 'It is not needed'), ('Без подписей диаграмму нельзя прочитать.', 'Without labels a chart cannot be read.')),
  Q('Что показывает линейный график?', 'What does a line graph show?', ('Как величина меняется со временем', 'How a quantity changes with time'), ('Только одно число', 'Only one number'), ('Цвета', 'Colours'), ('График связывает время и значение.', 'A graph links time and value.')),
  Q('Ось начинается с 35. Столбики 42 и 45. Какое утверждение верно?', 'The axis starts at 35. Bars 42 and 45. Which statement is true?', ('Разница на картинке кажется больше настоящей', 'The difference on the picture looks bigger than the real one'), ('Картинка точна', 'The picture is exact'), ('Столбики одинаковы', 'The bars are equal'), ('Обрезанная ось преувеличивает разницу.', 'A truncated axis exaggerates the difference.'))],
 src=[('Wikipedia: Bar chart', 'https://en.wikipedia.org/wiki/Bar_chart'), ('Wikipedia: Misleading graph', 'https://en.wikipedia.org/wiki/Misleading_graph')])
